import React, { useState } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [loading, setLoading] = useState(false);
  const [chatHistory, setChatHistory] = useState([]);

  // ✅ FIXED FUNCTION
  const handleSearch = async () => {
    if (!disease) return alert("Enter disease");

    setLoading(true);

    const userMessage = {
      type: "user",
      text: `${disease} ${intent} ${location}`,
    };

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
        }),
      });

      const data = await res.json();

      const botMessage = {
        type: "bot",
        summary: data.summary,
        publications: data.publications,
        trials: data.clinical_trials,
      };

      // ✅ Chat history update
      setChatHistory((prev) => [...prev, userMessage, botMessage]);

      // ✅ Update UI panels
      setSummary(data.summary || "");
      setPublications(data.publications || []);
      setTrials(data.clinical_trials || []);
    } catch (err) {
      console.error(err);
      alert("Backend error");
    }

    setLoading(false);
  };

  return (
    <div className="app">
      {/* LEFT PANEL */}
      <div className="sidebar">
        <h1>Curalink X</h1>
        <p>AI Medical Research Copilot</p>

        <input
          type="text"
          placeholder="e.g., Parkinson's disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="filters">
          <label>
            <input type="checkbox" defaultChecked />
            <span>Publications</span>
          </label>
          <label>
            <input type="checkbox" defaultChecked />
            <span>Clinical trials</span>
          </label>
          <label>
            <input type="checkbox" defaultChecked />
            <span>Risk analysis</span>
          </label>
        </div>
        </div>


        <div className="stats">
          <p>Research papers: {publications.length}</p>
          <p>Clinical trials: {trials.length}</p>
          <p>Risk confidence: 0%</p>
        </div>


      {/* CENTER PANEL */}
      <div className="main">
        <h1>OpenAI reasoning copilot</h1>

        {/* 💬 CHAT HISTORY */}
        <div className="chat-container">
          {chatHistory.map((msg, index) => (
            <div
              key={index}
              className={msg.type === "user" ? "user-msg" : "bot-msg"}
            >
              {msg.type === "user" ? (
                <p>{msg.text}</p>
              ) : (
                <div>
                  <p><strong>Summary:</strong> {msg.summary}</p>
                </div>
              )}
            </div>
          ))}
        </div>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
        />

        <button onClick={handleSearch}>
          {loading ? "Loading..." : "Send message"}
        </button>

        <div className="metadata">
          <input
            placeholder="Location"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
          />
        </div>

        {/* SUMMARY */}
        {summary && (
          <div className="summary">
            <h3>AI Summary</h3>
            <p>{summary}</p>
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div className="right">
        {/* PUBLICATIONS */}
        <div className="card">
          <h3>Research papers</h3>

          {publications.length === 0 ? (
            <p>No publication cards available yet</p>
          ) : (
            publications.map((pub, index) => (
              <div key={index} className="item">
                <h4>{pub.title}</h4>
                <p>{pub.year}</p>
                <a href={pub.link} target="_blank" rel="noreferrer">
                  View Paper
                </a>
              </div>
            ))
          )}
        </div>

        {/* TRIALS */}
        <div className="card">
          <h3>Clinical trials</h3>

          {trials.length === 0 ? (
            <p>No clinical trials matched the current filters.</p>
          ) : (
            trials.map((trial, index) => (
              <div key={index} className="item">
                <h4>{trial.title}</h4>
                <p>Status: {trial.status}</p>
              </div>
            ))
          )}
        </div>

        {/* RISK */}
        <div className="card">
          <h3>Risk analysis</h3>
          <p>Risk analysis will appear after the first evidence run.</p>
        </div>

        {/* WHAT IF */}
        <div className="card">
          <h3>What-if Analysis</h3>
          <input placeholder="e.g., Vitamin D" />
          <button>Simulate scenario</button>
        </div>
      </div>
    </div>
  );
}

export default App;
